(function() {
    'use strict';

    class PEPortfolioAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Private Equity Portfolio: Value Creation & Exit';
            this.version = '1.1.0';

            this.COMPANIES = {
                novamed:   { label: 'NovaMed Solutions',    entryEbitda: 10, entryMultiple: 9.5,  baseGrowth: 0.12, exitLow: 12, exitHigh: 18, covenantMax: 6.0, ipoEligible: true  },
                fortaleza: { label: 'Fortaleza Industrial', entryEbitda: 10, entryMultiple: 6.0,  baseGrowth: 0.06, exitLow: 7,  exitHigh: 9,  covenantMax: 5.0, ipoEligible: false },
                verdetech: { label: 'VerdeTech Agri',       entryEbitda: 6,  entryMultiple: 7.5,  baseGrowth: 0.08, exitLow: 10, exitHigh: 15, covenantMax: 5.5, ipoEligible: false },
                retail:    { label: 'Grupo Retail Express',  entryEbitda: 10, entryMultiple: 8.0,  baseGrowth: 0.03, exitLow: 5,  exitHigh: 7,  covenantMax: 5.5, ipoEligible: false }
            };

            this.EVENTS = [
                { title: 'LATAM Currency Pressure',       desc: 'Regional currencies weaken 8% against USD. Portfolio companies with USD-denominated debt face increased service costs. Fortaleza and VerdeTech net debt effectively rises.' },
                { title: 'IPO Window Opens for SaaS',     desc: 'Strong equity markets and investor appetite for healthcare SaaS create a premium IPO window. NovaMed could achieve top-range multiples if taken public this quarter.' },
                { title: 'Interest Rates Rise 150bps',    desc: 'Central banks tighten monetary policy. Floating-rate debt costs increase across all portfolio companies. Refinancing becomes significantly more expensive. Market multiples compress.' },
                { title: 'Strategic Buyer Approaches',     desc: 'A major global healthcare company reaches out about acquiring NovaMed off-market. Additionally, commodity prices surge, boosting AgriTech investment budgets.' }
            ];

            this.MNA_ROUNDS = [
                [
                    { id: 1, name: 'MediLink Peru',       co: 'novamed',   cost: 8,  ebitdaAdd: 1.5, desc: 'MediLink Peru (for NovaMed) — Regional EHR with 200 clinic clients. Cost: $8M, adds ~$1.5M EBITDA' },
                    { id: 2, name: 'AgroSense Colombia',   co: 'verdetech', cost: 5,  ebitdaAdd: 0.8, desc: 'AgroSense Colombia (for VerdeTech) — IoT sensors for coffee farms. Cost: $5M, adds ~$0.8M EBITDA' }
                ],
                [
                    { id: 1, name: 'CloudClin Mexico',     co: 'novamed',   cost: 12, ebitdaAdd: 2.2, desc: 'CloudClin Mexico (for NovaMed) — Cloud EHR with 500 clinics. Cost: $12M, adds ~$2.2M EBITDA' },
                    { id: 2, name: 'IrrigaTech Brazil',    co: 'verdetech', cost: 6,  ebitdaAdd: 1.0, desc: 'IrrigaTech Brazil (for VerdeTech) — AI irrigation startup. Cost: $6M, adds ~$1.0M EBITDA' }
                ],
                [
                    { id: 1, name: 'DataFarm Analytics',   co: 'verdetech', cost: 7,  ebitdaAdd: 1.2, desc: 'DataFarm Analytics (for VerdeTech) — Crop insurance data provider. Cost: $7M, adds ~$1.2M EBITDA' }
                ],
                []
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    companies: {
                        novamed:   { ebitda: 14,   netDebt: 38, equityInvested: 57, exited: false, exitProceeds: 0, vcpProgress: 0 },
                        fortaleza: { ebitda: 11.5, netDebt: 30, equityInvested: 30, exited: false, exitProceeds: 0, vcpProgress: 0 },
                        verdetech: { ebitda: 7,    netDebt: 15, equityInvested: 30, exited: false, exitProceeds: 0, vcpProgress: 0 },
                        retail:    { ebitda: 8.5,  netDebt: 45, equityInvested: 35, exited: false, exitProceeds: 0, vcpProgress: 0 }
                    },
                    totalEquityDeployed: 152,
                    remainingCapital: 48,
                    totalDistributions: 0,
                    marketCondition: 1.0,
                    ipoWindowOpen: false,
                    covenantBreaches: 0,
                    currentEventTitle: '',
                    currentEventDesc: '',
                    portfolioNavHistory: [],
                    fundMoicHistory: [],
                    novamedEbitdaHist: [],
                    fortalezaEbitdaHist: [],
                    verdetechEbitdaHist: [],
                    retailEbitdaHist: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    novamedAttention: 25,
                    fortalezaAttention: 25,
                    verdetechAttention: 25,
                    retailAttention: 25,
                    novamedCapital: 'none',
                    fortalezaCapital: 'none',
                    verdetechCapital: 'none',
                    retailCapital: 'none',
                    novamedExit: 'hold',
                    fortalezaExit: 'hold',
                    verdetechExit: 'hold',
                    retailExit: 'hold',
                    pursueMnA1: false,
                    pursueMnA2: false
                };
            }
            this._updateBriefing(state);
            this._setupAttentionListener();
        }

        _setupAttentionListener() {
            var ids = ['novamedAttention','fortalezaAttention','verdetechAttention','retailAttention'];
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var total = 0;
                        ids.forEach(function(iid) {
                            var e = document.getElementById(iid);
                            if (e) total += parseInt(e.value) || 0;
                        });
                        var display = document.getElementById('attentionTotalDisplay');
                        if (display) {
                            display.textContent = 'Total: ' + total + ' / 100';
                            if (total !== 100) {
                                display.classList.add('pe-sim-over');
                            } else {
                                display.classList.remove('pe-sim-over');
                            }
                        }
                    });
                }
            });
        }

        _updateBriefing(state) {
            var period = (state.currentPeriod || 1);
            var idx = Math.min(period - 1, this.EVENTS.length - 1);
            var evt = this.EVENTS[idx];

            var titleEl = document.getElementById('eventTitle');
            if (titleEl) titleEl.innerHTML = evt.title;
            var descEl = document.getElementById('eventDescription');
            if (descEl) descEl.innerHTML = evt.desc;

            var mnaTargets = this.MNA_ROUNDS[Math.min(idx, this.MNA_ROUNDS.length - 1)];
            var t1 = document.getElementById('mnaTarget1');
            var t2 = document.getElementById('mnaTarget2');
            var ph = document.getElementById('mnaPlaceholder');
            var cb1 = document.getElementById('pursueMnA1');
            var cb2 = document.getElementById('pursueMnA2');

            if (t1) t1.style.display = 'none';
            if (t2) t2.style.display = 'none';
            if (ph) ph.style.display = 'block';
            if (cb1) cb1.checked = false;
            if (cb2) cb2.checked = false;

            if (mnaTargets && mnaTargets.length > 0) {
                if (ph) ph.style.display = 'none';
                if (mnaTargets[0]) {
                    if (t1) t1.style.display = 'block';
                    var d1 = document.getElementById('mnaTarget1Desc');
                    if (d1) d1.textContent = mnaTargets[0].desc;
                }
                if (mnaTargets[1]) {
                    if (t2) t2.style.display = 'block';
                    var d2 = document.getElementById('mnaTarget2Desc');
                    if (d2) d2.textContent = mnaTargets[1].desc;
                }
            }

            var keys = ['novamed','fortaleza','verdetech','retail'];
            var ds = state.domainState;
            if (ds && ds.companies) {
                var self = this;
                keys.forEach(function(k) {
                    var co = ds.companies[k];
                    var exitSel = document.getElementById(k + 'Exit');
                    var attInput = document.getElementById(k + 'Attention');
                    var capSel = document.getElementById(k + 'Capital');
                    if (co && co.exited) {
                        if (exitSel) exitSel.disabled = true;
                        if (attInput) { attInput.disabled = true; attInput.value = 0; }
                        if (capSel) capSel.disabled = true;
                    } else {
                        if (exitSel) exitSel.disabled = false;
                        if (attInput) attInput.disabled = false;
                        if (capSel) capSel.disabled = false;
                    }
                    if (k === 'novamed' && exitSel) {
                        var ipoOpt = exitSel.querySelector('option[value="ipo"]');
                        if (ipoOpt) {
                            if (period >= 2 && period <= 3 && ds.ipoWindowOpen) {
                                ipoOpt.disabled = false;
                            } else if (period === 2) {
                                ipoOpt.disabled = false;
                            } else {
                                ipoOpt.disabled = true;
                            }
                        }
                    }
                });
            }
        }

        validateDecisions(decisions) {
            var na = document.getElementById('novamedAttention');
            var fa = document.getElementById('fortalezaAttention');
            var va = document.getElementById('verdetechAttention');
            var ra = document.getElementById('retailAttention');
            if (na) decisions.novamedAttention = parseInt(na.value) || 0;
            if (fa) decisions.fortalezaAttention = parseInt(fa.value) || 0;
            if (va) decisions.verdetechAttention = parseInt(va.value) || 0;
            if (ra) decisions.retailAttention = parseInt(ra.value) || 0;

            var total = decisions.novamedAttention + decisions.fortalezaAttention + decisions.verdetechAttention + decisions.retailAttention;
            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('attention_warning'), 'warning'
                );
                return false;
            }
            if (decisions.novamedAttention < 0 || decisions.fortalezaAttention < 0 || decisions.verdetechAttention < 0 || decisions.retailAttention < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('attention_negative'), 'warning'
                );
                return false;
            }

            var nc = document.getElementById('novamedCapital');
            var fc = document.getElementById('fortalezaCapital');
            var vc = document.getElementById('verdetechCapital');
            var rc = document.getElementById('retailCapital');
            if (nc) decisions.novamedCapital = nc.value;
            if (fc) decisions.fortalezaCapital = fc.value;
            if (vc) decisions.verdetechCapital = vc.value;
            if (rc) decisions.retailCapital = rc.value;

            var ne = document.getElementById('novamedExit');
            var fe = document.getElementById('fortalezaExit');
            var ve = document.getElementById('verdetechExit');
            var re = document.getElementById('retailExit');
            if (ne) decisions.novamedExit = ne.value;
            if (fe) decisions.fortalezaExit = fe.value;
            if (ve) decisions.verdetechExit = ve.value;
            if (re) decisions.retailExit = re.value;

            var m1 = document.getElementById('pursueMnA1');
            var m2 = document.getElementById('pursueMnA2');
            decisions.pursueMnA1 = m1 ? m1.checked : false;
            decisions.pursueMnA2 = m2 ? m2.checked : false;

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var evtIdx = Math.min(period - 1, this.EVENTS.length - 1);
            var companies = ds.companies;
            var keys = ['novamed','fortaleza','verdetech','retail'];
            var attentionMap = { novamed: d.novamedAttention, fortaleza: d.fortalezaAttention, verdetech: d.verdetechAttention, retail: d.retailAttention };
            var capitalMap = { novamed: d.novamedCapital, fortaleza: d.fortalezaCapital, verdetech: d.verdetechCapital, retail: d.retailCapital };
            var exitMap = { novamed: d.novamedExit, fortaleza: d.fortalezaExit, verdetech: d.verdetechExit, retail: d.retailExit };
            var self = this;
            var quarterDistributions = 0;
            var exitsThisQuarter = [];
            var covenantBreachesThisQ = [];

            if (evtIdx === 0) {
                companies.fortaleza.netDebt = Math.round(companies.fortaleza.netDebt * 1.04 * 100) / 100;
                companies.verdetech.netDebt = Math.round(companies.verdetech.netDebt * 1.04 * 100) / 100;
            } else if (evtIdx === 1) {
                ds.ipoWindowOpen = true;
                ds.marketCondition = Math.min(ds.marketCondition * 1.12, 1.3);
            } else if (evtIdx === 2) {
                keys.forEach(function(k) {
                    if (!companies[k].exited) {
                        companies[k].netDebt = Math.round(companies[k].netDebt * 1.025 * 100) / 100;
                    }
                });
                ds.marketCondition = Math.max(ds.marketCondition * 0.88, 0.7);
                ds.ipoWindowOpen = false;
            } else if (evtIdx === 3) {
                ds.marketCondition = Math.min(ds.marketCondition * 1.08, 1.3);
            }

            ds.currentEventTitle = self.EVENTS[evtIdx].title;
            ds.currentEventDesc = self.EVENTS[evtIdx].desc;

            var companyResults = {};

            keys.forEach(function(k) {
                var co = companies[k];
                var cfg = self.COMPANIES[k];
                if (co.exited) {
                    companyResults[k] = { ebitda: co.ebitda, netDebt: co.netDebt, leverage: 0, equityValue: co.exitProceeds, status: 'exited', action: 'Exited' };
                    return;
                }

                var attention = attentionMap[k] || 0;
                var attFactor = attention / 25.0;
                var variance = 0.85 + (Math.sin(period * 137 + attention * 17 + k.length * 53) * 0.5 + 0.5) * 0.3;
                var ebitdaGrowth = cfg.baseGrowth * attFactor * variance;

                if (attFactor < 0.6) {
                    ebitdaGrowth = ebitdaGrowth * 0.5;
                    if (k === 'retail') ebitdaGrowth = -0.04;
                }

                co.ebitda = Math.round((co.ebitda * (1 + ebitdaGrowth)) * 100) / 100;
                co.vcpProgress = Math.min(100, co.vcpProgress + attention * 0.8);

                var fcf = co.ebitda * 0.25;
                co.netDebt = Math.round(Math.max(0, co.netDebt - fcf) * 100) / 100;

                var capAction = capitalMap[k];
                if (capAction === 'refinance') {
                    co.netDebt = Math.round(co.netDebt * 0.95 * 100) / 100;
                } else if (capAction === 'dividend_recap') {
                    var recapAmount = Math.round(co.ebitda * 0.5 * 100) / 100;
                    co.netDebt = Math.round((co.netDebt + recapAmount) * 100) / 100;
                    quarterDistributions += recapAmount;
                } else if (capAction === 'equity_injection') {
                    if (ds.remainingCapital >= 5) {
                        co.netDebt = Math.round(Math.max(0, co.netDebt - 5) * 100) / 100;
                        ds.remainingCapital -= 5;
                        ds.totalEquityDeployed += 5;
                        co.equityInvested += 5;
                    }
                }

                var leverage = co.ebitda > 0 ? co.netDebt / co.ebitda : 99;
                if (leverage > cfg.covenantMax) {
                    ds.covenantBreaches += 1;
                    covenantBreachesThisQ.push(cfg.label);
                    co.ebitda = Math.round(co.ebitda * 0.92 * 100) / 100;
                }

                var exitDecision = exitMap[k];
                if (exitDecision !== 'hold') {
                    var exitMultiple = 0;
                    if (exitDecision === 'ipo' && cfg.ipoEligible && ds.ipoWindowOpen) {
                        exitMultiple = cfg.exitHigh * ds.marketCondition * (1 + co.vcpProgress / 300);
                    } else if (exitDecision === 'strategic') {
                        exitMultiple = ((cfg.exitLow + cfg.exitHigh) / 2) * ds.marketCondition * 1.1;
                    } else if (exitDecision === 'secondary') {
                        exitMultiple = cfg.exitLow * ds.marketCondition * 1.02;
                    } else if (exitDecision === 'ipo') {
                        exitMultiple = ((cfg.exitLow + cfg.exitHigh) / 2) * ds.marketCondition * 0.9;
                    }

                    if (exitMultiple > 0) {
                        var tev = Math.round(co.ebitda * exitMultiple * 100) / 100;
                        var exitEquity = Math.round(Math.max(0, tev - co.netDebt) * 100) / 100;
                        co.exitProceeds = exitEquity;
                        co.exited = true;
                        quarterDistributions += exitEquity;
                        exitsThisQuarter.push(cfg.label + ' (' + exitDecision.toUpperCase() + ' at ' + exitMultiple.toFixed(1) + 'x for $' + exitEquity.toFixed(1) + 'M)');
                    }
                }

                var currentMultiple = (cfg.exitLow + cfg.exitHigh) / 2 * ds.marketCondition;
                var estEquity = co.exited ? co.exitProceeds : Math.round(Math.max(0, co.ebitda * currentMultiple - co.netDebt) * 100) / 100;
                var coMoic = co.equityInvested > 0 ? Math.round(estEquity / co.equityInvested * 100) / 100 : 0;

                companyResults[k] = {
                    ebitda: co.ebitda,
                    netDebt: co.netDebt,
                    leverage: co.ebitda > 0 ? Math.round(co.netDebt / co.ebitda * 10) / 10 : 0,
                    equityValue: estEquity,
                    moic: coMoic,
                    status: co.exited ? 'exited' : (leverage > cfg.covenantMax ? 'breach' : 'active'),
                    action: capAction !== 'none' ? capAction : '-'
                };
            });

            var mnaRound = self.MNA_ROUNDS[Math.min(period - 1, self.MNA_ROUNDS.length - 1)];
            var mnaExecuted = [];
            if (d.pursueMnA1 && mnaRound && mnaRound[0]) {
                var t = mnaRound[0];
                var co = companies[t.co];
                if (!co.exited && ds.remainingCapital >= t.cost) {
                    ds.remainingCapital -= t.cost;
                    ds.totalEquityDeployed += t.cost;
                    co.equityInvested += t.cost;
                    co.ebitda = Math.round((co.ebitda + t.ebitdaAdd * 0.5) * 100) / 100;
                    co.netDebt = Math.round((co.netDebt + t.cost * 0.6) * 100) / 100;
                    mnaExecuted.push(t.name);
                }
            }
            if (d.pursueMnA2 && mnaRound && mnaRound[1]) {
                var t2 = mnaRound[1];
                var co2 = companies[t2.co];
                if (!co2.exited && ds.remainingCapital >= t2.cost) {
                    ds.remainingCapital -= t2.cost;
                    ds.totalEquityDeployed += t2.cost;
                    co2.equityInvested += t2.cost;
                    co2.ebitda = Math.round((co2.ebitda + t2.ebitdaAdd * 0.5) * 100) / 100;
                    co2.netDebt = Math.round((co2.netDebt + t2.cost * 0.6) * 100) / 100;
                    mnaExecuted.push(t2.name);
                }
            }

            ds.totalDistributions = Math.round((ds.totalDistributions + quarterDistributions) * 100) / 100;

            var totalUnrealized = 0;
            keys.forEach(function(k) {
                totalUnrealized += companyResults[k].equityValue || 0;
            });
            totalUnrealized = Math.round(totalUnrealized * 100) / 100;

            var totalValue = ds.totalDistributions + totalUnrealized;
            var fundMoic = ds.totalEquityDeployed > 0 ? Math.round(totalValue / ds.totalEquityDeployed * 100) / 100 : 0;
            var yearsElapsed = period * 0.5;
            var fundIrr = yearsElapsed > 0 && fundMoic > 0 ? Math.round((Math.pow(fundMoic, 1 / yearsElapsed) - 1) * 10000) / 100 : 0;

            // v1.1.0 fix: persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            var composite = this._composite(fundMoic, fundIrr);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = composite;

            ds.portfolioNavHistory.push(totalValue);
            ds.fundMoicHistory.push(fundMoic);
            ds.novamedEbitdaHist.push(companies.novamed.ebitda);
            ds.fortalezaEbitdaHist.push(companies.fortaleza.ebitda);
            ds.verdetechEbitdaHist.push(companies.verdetech.ebitda);
            ds.retailEbitdaHist.push(companies.retail.ebitda);

            var self2 = this;
            setTimeout(function() {
                self2._updateBriefing({ currentPeriod: period + 1, domainState: ds });
            }, 500);

            return {
                period: period,
                overallScore: composite,
                score: composite,
                totalEbitda: Math.round((companies.novamed.ebitda + companies.fortaleza.ebitda + companies.verdetech.ebitda + companies.retail.ebitda) * 100) / 100,
                portfolioNav: totalUnrealized,
                quarterDistributions: Math.round(quarterDistributions * 100) / 100,
                cumulativeDistributions: ds.totalDistributions,
                fundMoic: fundMoic,
                fundIrr: fundIrr,
                marketCondition: Math.round(ds.marketCondition * 100) / 100,
                covenantBreaches: covenantBreachesThisQ.length > 0 ? covenantBreachesThisQ.join(', ') : 'None',
                exits: exitsThisQuarter.length > 0 ? exitsThisQuarter.join('; ') : 'None',
                mnaExecuted: mnaExecuted.length > 0 ? mnaExecuted.join(', ') : 'None',
                companyResults: companyResults,
                novamedEbitda: companies.novamed.ebitda,
                fortalezaEbitda: companies.fortaleza.ebitda,
                verdetechEbitda: companies.verdetech.ebitda,
                retailEbitda: companies.retail.ebitda
            };
        }

